file.content:
        if reason not in _PAFD_REASONS:
            raise _pfda_invalid(f"{where} entry reason is not known")
    if conclusion == _PAFD_CONCLUSION_INVALID:
        if reason not in _PAFD_INVALID_REASONS:
            raise _pfda_invalid(
                f"{where} entry reason does not match an invalid item"
            )
    elif conclusion != _PAFD_CONCLUSION_VALID:
        if reason != conclusion:
            raise _pfda_invalid(
                f"{where} entry reason must match its conclusion"
            )
    raw_edges = value[PAFD_EDGES]
    if raw_edges is not None:
        if not isinstance(raw_edges, list):
            raise TypeError(f"{where} entry edges must be a list or null")
        if not raw_edges:
            raise _pfda_invalid(
                f"{where} entry edges must be non-empty for an "
                "authenticated proof"
            )
        edges = [
            _validated_pafd_edge(edge_value, where)
            for edge_value in raw_edges
        ]
        triples = _pac_fork_edge_triples(edges)
        if len(set(triples)) != len(triples):
            raise _pfda_invalid(f"{where} entry edges must be unique")
        if list(triples) != sorted(triples):
            raise _pfda_invalid(
                f"{where} entry edges must be sorted ascending"
            )
    else:
        edges = None
    identity_expected = reason != _PAFD_REASON_INVALID_PROOF
    if identity_expected:
        if site is None or edges is None:
            raise _pfda_invalid(
                f"{where} an authenticated entry must carry its site and "
                "fork edges"
            )
    elif site is not None or edges is not None:
        raise _pfda_invalid(
            f"{where} an invalid-proof entry must carry no site or fork "
            "edges"
        )
    return {
        ADJ_CONCLUSION: conclusion,
        CP_DIGEST: digest,
        PAFD_EDGES: edges,
        ID: entry_id,
        ADJ_REASON: reason,
        VD_ISSUER: site,
    }


def _validated_pfda_declaration(value: object, where: str) -> dict | None:
    """Structurally validate one complete declaration into a fresh dict.

    The declaration carries exactly ``common`` (the common fork edge
    set, or null), ``conclusions`` (the per-item conclusion entries,
    sorted by site then id), ``proofs`` (the original-order proof
    digest vector) and ``status``; a conflicted status binds no common
    set and an accepted status must bind one.
    """
    if value is None:
        return None
    if not isinstance(value, dict):
        raise TypeError(f"{where} must be an object or null")
    if set(value.keys()) != _PFDA_DECLARATION_KEYS:
        raise _pfda_invalid(
            f"{where} must contain exactly the keys 'common', "
            "'conclusions', 'proofs' and 'status'"
        )
    status = value[STATUS]
    if not isinstance(status, str):
        raise TypeError(f"{where} status must be a str")
    if status not in _PAFD_STATUSES:
        raise _pfda_invalid(f"{where} status is not a known status")

    common = value[PAFD_COMMON]
    if common is not None:
        if not isinstance(common, list):
            raise TypeError(f"{where} common must be a list or null")
        if not common:
            raise _pfda_invalid(
                f"{where} a bound common edge set must be non-empty"
            )
        common_edges = [
            _validated_pafd_edge(edge_value, f"{where} common")
            for edge_value in common
        ]
        common_triples = _pac_fork_edge_triples(common_edges)
        if len(set(common_triples)) != len(common_triples) or list(
            common_triples
        ) != sorted(common_triples):
            raise _pfda_invalid(
                f"{where} common edges must be unique and sorted ascending"
            )
    else:
        common_edges = None
    if status == _PAFD_STATUS_CONFLICTED and common is not None:
        raise _pfda_invalid(
            f"{where} a conflicted declaration must bind no common set"
        )
    if status == _PAFD_STATUS_ACCEPTED and common is None:
        raise _pfda_invalid(
            f"{where} an accepted declaration must bind its common set"
        )

    raw_entries = value[PFDA_CONCLUSIONS]
    if not isinstance(raw_entries, list):
        raise TypeError(f"{where} conclusions must be a list")
    if not raw_entries:
        raise _pfda_invalid(f"{where} conclusions must be non-empty")
    entries = [
        _validated_pfda_declaration_entry(entry_value, where)
        for entry_value in raw_entries
    ]
    entry_ids = [entry[ID] for entry in entries]
    if len(set(entry_ids)) != len(entry_ids):
        raise _pfda_invalid(f"{where} conclusions must not repeat an id")
    expected_order = sorted(
        entries,
        key=lambda entry: (
            entry[VD_ISSUER] is not None,
            entry[VD_ISSUER] or "",
            entry[ID],
        ),
    )
    if [entry[ID] for entry in expected_order] != entry_ids:
        raise _pfda_invalid(
            f"{where} conclusions must be sorted by site then id"
        )

    proofs = value[PFDA_PROOFS]
    if not isinstance(proofs, list):
        raise TypeError(f"{where} proofs must be a list")
    if not proofs:
        raise _pfda_invalid(f"{where} proofs must be non-empty")
    for position, digest in enumerate(proofs):
        if not isinstance(digest, str):
            raise TypeError(f"{where} proof {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise _pfda_invalid(
                f"{where} proof {position} digest must be 64 lowercase hex "
                "characters"
            )
    if len(proofs) != len(entries):
        raise _pfda_invalid(
            f"{where} the conclusions must cover every proof and vice versa"
        )
    if sorted(proofs) != sorted(entry[CP_DIGEST] for entry in entries):
        raise _pfda_invalid(
            f"{where} the bound proof digests must equal the per-entry "
            "digests"
        )

    return {
        PAFD_COMMON: common_edges,
        PFDA_CONCLUSIONS: entries,
        PFDA_PROOFS: list(proofs),
        STATUS: status,
    }


def _parse_pfda(raw: object) -> tuple[dict, str]:
    """Validate aggregate bytes structurally into ``(payload, signature)``.

    A non-bytes argument or a public field of the wrong JSON type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, ordering, row-shape or
    declaration-shape fault raises
    :class:`InvalidAggregateForkDecisionAggregateError`.  The policy
    digests, tally and credential bindings are checked by
    :func:`verify_prune_fork_decision_aggregate`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("aggregate packet must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _pfda_invalid(
            "aggregate packet must end with the closing brace, no "
            "trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _pfda_invalid("aggregate packet is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_pfda_keys
        )
    except json.JSONDecodeError as exc:
        raise _pfda_invalid("aggregate packet is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("aggregate packet must be a JSON object")
    if set(data.keys()) != _PFDA_TOP_KEYS:
        raise _pfda_invalid(
            "aggregate packet must contain exactly the keys 'payload' and "
            "'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("aggregate packet signature must be a str")
    if not _prune_is_digest(signature):
        raise _pfda_invalid(
            "aggregate packet signature must be 64 lowercase hex characters"
        )

    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("aggregate packet payload must be an object")
    if set(payload.keys()) != _PFDA_PAYLOAD_KEYS:
        raise _pfda_invalid(
            "aggregate packet payload must contain exactly the keys "
            "'inputs', 'issuer', 'items', 'keyVersion', "
            "'prunePolicyDigest', 'sitePolicyDigest', "
            "'decisionSitePolicyDigest', 'declaration', 'status' and "
            "'version'"
        )

    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("aggregate payload issuer must be a str")
    if issuer == "":
        raise _pfda_invalid("aggregate payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("aggregate payload keyVersion must be an int")
    if key_version <= 0:
        raise _pfda_invalid("aggregate payload keyVersion must be positive")
    for field in (
        PFDA_PRUNE_POLICY_DIGEST,
        PFDA_SITE_POLICY_DIGEST,
        PFDA_DECISION_SITE_POLICY_DIGEST,
    ):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"aggregate payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise _pfda_invalid(
                f"aggregate payload {field} must be 64 lowercase hex "
                "characters"
            )
    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("aggregate status must be a str")
    if status not in _PA_STATUSES:
        raise _pfda_invalid("aggregate status is not a known status")
    version = payload[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("aggregate payload version must be an int")
    if version != PRUNE_FORK_DECISION_AGGREGATE_VERSION:
        raise _pfda_invalid("aggregate payload version must be the integer 1")

    inputs = payload[PFDA_INPUTS]
    if not isinstance(inputs, list):
        raise TypeError("aggregate inputs must be a list")
    if not inputs:
        raise _pfda_invalid("aggregate inputs must be a non-empty list")
    for position, digest in enumerate(inputs):
        if not isinstance(digest, str):
            raise TypeError(f"aggregate input {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise _pfda_invalid(
                f"aggregate input {position} digest must be 64 lowercase "
                "hex characters"
            )

    rows = payload[ITEMS]
    if not isinstance(rows, list):
        raise TypeError("aggregate items must be a list")
    if not rows:
        raise _pfda_invalid("aggregate items must be a non-empty list")
    if len(rows) != len(inputs):
        raise _pfda_invalid(
            "the items must cover every input and vice versa"
        )
    seen_row_ids: set[str] = set()
    parsed_rows: list[dict] = []
    for position, row in enumerate(rows):
        where = f"aggregate item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{where} must be an object")
        if set(row.keys()) != _PFDA_ROW_KEYS:
            raise _pfda_invalid(
                f"{where} must contain exactly the keys 'conclusion', "
                "'digest', 'id', 'issuer', 'keyVersion', 'reason' and "
                "'declaration'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{where} id must be a str")
        if row_id == "":
            raise _pfda_invalid(f"{where} id must be non-empty")
        if row_id in seen_row_ids:
            raise _pfda_invalid(f"{where} repeats an id")
        seen_row_ids.add(row_id)
        digest = row[CP_DIGEST]
        if not isinstance(digest, str):
            raise TypeError(f"{where} digest must be a str")
        if not _prune_is_digest(digest):
            raise _pfda_invalid(
                f"{where} digest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None and not isinstance(site, str):
            raise TypeError(f"{where} issuer must be a str or null")
        if site == "":
            raise _pfda_invalid(f"{where} issuer must be non-empty")
        row_key_version = row[KEY_VERSION]
        if isinstance(row_key_version, bool) or not isinstance(
            row_key_version, int
        ):
            if row_key_version is not None:
                raise TypeError(f"{where} keyVersion must be an int or null")
        elif row_key_version <= 0:
            raise _pfda_invalid(f"{where} keyVersion must be positive")
        if (site is None) != (row_key_version is None):
            raise _pfda_invalid(
                f"{where} issuer and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]
        if not isinstance(conclusion, str):
            raise TypeError(f"{where} conclusion must be a str")
        reason = row[ADJ_REASON]
        if conclusion == PA_CONCLUSION_VALID:
            if reason is not None:
                raise _pfda_invalid(
                    f"{where} reason must be null for a valid row"
                )
        elif conclusion == PA_CONCLUSION_INVALID:
            if reason not in _PFDA_INVALID_REASONS:
                raise _pfda_invalid(
                    f"{where} reason must be one of 'invalid', "
                    "'unauthenticated' or 'unauthorized'"
                )
        elif conclusion in (
            PA_CONCLUSION_DUPLICATE, PA_CONCLUSION_CONTRADICTION
        ):
            expected = (
                REASON_DUPLICATE
                if conclusion == PA_CONCLUSION_DUPLICATE
                else REASON_CONTRADICTION
            )
            if reason != expected:
                raise _pfda_invalid(
                    f"{where} reason must match its conclusion"
                )
        else:
            raise _pfda_invalid(f"{where} conclusion is not known")
        identity_present = reason != PA_CONCLUSION_INVALID
        if identity_present:
            if site is None:
                raise _pfda_invalid(
                    f"{where} an authenticated or authorized row must carry "
                    "its issuer"
                )
        elif site is not None:
            raise _pfda_invalid(
                f"{where} an invalid row must carry no issuer"
            )
        raw_declaration = row[PFDA_DECLARATION]
        if conclusion == PA_CONCLUSION_INVALID:
            if raw_declaration is not None:
                raise _pfda_invalid(
                    f"{where} an invalid row must carry no declaration"
                )
            parsed_declaration = None
        else:
            parsed_declaration = _validated_pfda_declaration(
                raw_declaration, f"{where} declaration"
            )
            if parsed_declaration is None:
                raise _pfda_invalid(
                    f"{where} a counted row must carry its declaration"
                )
        parsed_rows.append({
            ADJ_CONCLUSION: conclusion,
            CP_DIGEST: digest,
            ID: row_id,
            VD_ISSUER: site,
            KEY_VERSION: row_key_version,
            ADJ_REASON: reason,
            PFDA_DECLARATION: parsed_declaration,
        })

    common_declaration = _validated_pfda_declaration(
        payload[PFDA_DECLARATION], "aggregate declaration"
    )

    normalized_payload = {
        PFDA_INPUTS: list(inputs),
        VD_ISSUER: issuer,
        ITEMS: parsed_rows,
        KEY_VERSION: key_version,
        PFDA_PRUNE_POLICY_DIGEST: payload[PFDA_PRUNE_POLICY_DIGEST],
        PFDA_SITE_POLICY_DIGEST: payload[PFDA_SITE_POLICY_DIGEST],
        PFDA_DECISION_SITE_POLICY_DIGEST: payload[
            PFDA_DECISION_SITE_POLICY_DIGEST
        ],
        PFDA_DECLARATION: common_declaration,
        STATUS: status,
        VERSION: PRUNE_FORK_DECISION_AGGREGATE_VERSION,
    }
    if _prune_compact({TICKET_PAYLOAD: normalized_payload,
                       SIGNATURE: signature}) != raw:
        raise _pfda_invalid(
            "aggregate packet encoding is not the canonical compact form"
        )
    return normalized_payload, signature


def _reconcile_pfda_declaration(
    declaration: dict, fork_threshold: int, where: str
) -> None:
    """Re-tally one bound declaration as the decision it claims to be.

    The declaration's per-item conclusion entries and original-order
    proof digest vector are re-tallied through the exact
    :func:`_reconcile_pafd` rules against the fork-proof site policy
    threshold, so a reordered entry, a wrong duplicate or contradiction
    marking, a tampered common set or a mis-stated status cannot hide
    inside a counted declaration.  Any mismatch raises
    :class:`InvalidAggregateForkDecisionAggregateError`.
    """
    synthetic_payload = {
        PAFD_COMMON: declaration[PAFD_COMMON],
        ITEMS: [
            {
                ADJ_CONCLUSION: entry[ADJ_CONCLUSION],
                PAFD_EDGES: entry[PAFD_EDGES],
                ID: entry[ID],
                KEY_VERSION: None,
                PAFD_FORK_PROOF_DIGEST: entry[CP_DIGEST],
                ADJ_REASON: entry[ADJ_REASON],
                VD_ISSUER: entry[VD_ISSUER],
            }
            for entry in declaration[PFDA_CONCLUSIONS]
        ],
        PAFD_PROOFS: declaration[PFDA_PROOFS],
        STATUS: declaration[STATUS],
    }
    try:
        _reconcile_pafd(synthetic_payload, fork_threshold)
    except InvalidAggregateForkDecisionError as exc:
        raise _pfda_invalid(f"{where}: {exc}") from exc


def _reconcile_pfda_aggregate(
    payload: dict, fork_threshold: int, decision_threshold: int
) -> None:
    """Re-derive every aggregate binding of a parsed aggregate payload.

    Re-tallies the per-decision rows the signature covers -- the
    original-order input digest bindings, row ordering, same-site
    duplicate and contradiction markings, cross-site complete
    declaration agreement, the threshold acceptance and the claimed
    common declaration and status -- and re-tallies every counted
    declaration against the fork-proof site policy threshold, without
    seeing any decision bytes.  Any mismatch raises
    :class:`InvalidAggregateForkDecisionAggregateError`.
    """
    rows = payload[ITEMS]
    inputs = payload[PFDA_INPUTS]

    expected_order = sorted(
        rows,
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        ),
    )
    if [row[ID] for row in expected_order] != [row[ID] for row in rows]:
        raise _pfda_invalid("items must be sorted by issuer then id")
    if sorted(row[CP_DIGEST] for row in rows) != sorted(inputs):
        raise _pfda_invalid(
            "the bound input digests must equal the per-item digests"
        )

    # Deep-copy the parsed rows before the tally mutates their
    # conclusion/reason markings; the signed payload itself is compared
    # through freshly derived structures only.
    working_rows = copy.deepcopy(rows)
    derived_status, derived_declaration = _tally_pfda_rows(
        working_rows, decision_threshold
    )

    for expected_row, bound_row in zip(working_rows, rows):
        if expected_row[ADJ_CONCLUSION] != bound_row[ADJ_CONCLUSION]:
            raise _pfda_invalid(
                f"item {bound_row[ID]!r} has the wrong conclusion"
            )
        if expected_row[ADJ_REASON] != bound_row[ADJ_REASON]:
            raise _pfda_invalid(
                f"item {bound_row[ID]!r} has the wrong reason"
            )

    if payload[STATUS] != derived_status:
        raise _pfda_invalid(
            "the bound status does not match the tallied items"
        )
    bound_declaration = payload[PFDA_DECLARATION]
    if derived_declaration is None:
        if bound_declaration is not None:
            raise _pfda_invalid(
                "the common declaration must be null when no unique "
                "conflict-free declaration was tallied"
            )
    else:
        if bound_declaration is None:
            raise _pfda_invalid(
                "an aggregate over one unique conflict-free declaration "
                "must carry the common declaration"
            )
        if bound_declaration != derived_declaration:
            raise _pfda_invalid(
                "the bound common declaration does not match the tallied "
                "decisions"
            )

    # Every counted declaration must itself re-tally as the decision it
    # claims to be, purely from its bound conclusions and proof vector.
    for row in rows:
        declaration = row[PFDA_DECLARATION]
        if declaration is None:
            continue
        _reconcile_pfda_declaration(
            declaration, fork_threshold, f"aggregate item {row[ID]!r}"
        )
    if bound_declaration is not None:
        _reconcile_pfda_declaration(
            bound_declaration, fork_threshold, "aggregate declaration"
        )


def _verify_pfda_core(
    aggregate: bytes,
    validated_prune_policy: dict,
    validated_site_policy: dict,
    validated_decision_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one fork-decision aggregate from validated shared materials."""
    payload, signature = _parse_pfda(aggregate)
    expected_prune_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[PFDA_PRUNE_POLICY_DIGEST] != expected_prune_digest:
        raise _pfda_invalid(
            "prune policy digest does not match the prune policy"
        )
    expected_site_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    if payload[PFDA_SITE_POLICY_DIGEST] != expected_site_digest:
        raise _pfda_invalid(
            "site policy digest does not match the site policy"
        )
    expected_decision_site_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_decision_site_policy)
    ).hexdigest()
    if payload[PFDA_DECISION_SITE_POLICY_DIGEST] != (
        expected_decision_site_digest
    ):
        raise _pfda_invalid(
            "decision site policy digest does not match the decision "
            "site policy"
        )

    _reconcile_pfda_aggregate(
        payload,
        validated_site_policy[ADJ_THRESHOLD],
        validated_decision_site_policy[ADJ_THRESHOLD],
    )

    entry = _usable_checkpoint_key(
        validated_keyring,
        payload[VD_ISSUER],
        payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "prune fork decision aggregate signature does not match"
        )
    return payload


def verify_prune_fork_decision_aggregate(
    aggregate, prune_policy, site_policy, decision_site_policy,
    keyring, moment,
):
    """Verify a signed cross-site fork-decision aggregate entirely offline.

    Only the aggregate bytes, the expected shared ``prune_policy``, the
    expected fork-proof ``site_policy``, the expected
    ``decision_site_policy``, the current ``keyring`` and the
    verification ``moment`` are consulted -- no file is read or written
    and no argument is modified.  Verification validates the canonical
    encoding and every key set, recomputes all three policy digests,
    and re-tallies the bound per-decision rows purely from the signed
    payload: the original-order input digest bindings, the issuer/id
    row ordering, same-site duplicate and contradiction markings,
    cross-site complete declaration agreement (the common fork edge
    set, the per-item conclusions and the overall status together), the
    threshold outcome and the claimed common declaration, together with
    a full re-tally of every counted declaration against the fork-proof
    site policy threshold.  It then checks the HMAC-SHA256 against the
    key the *current* keyring binds to the payload's exact issuer and
    version, usable at the verification moment, so a later revocation
    or expiry rejects the aggregate with no fallback.

    On success a fresh dict equal to the authenticated payload plus
    ``aggregateDigest`` (the SHA-256 of the aggregate bytes) is
    returned with the fixed keys ``aggregateDigest``, ``inputs``,
    ``issuer``, ``items``, ``keyVersion``, ``prunePolicyDigest``,
    ``sitePolicyDigest``, ``decisionSitePolicyDigest``, ``declaration``,
    ``status`` and ``version`` (the integer 1) -- repeated calls return
    equal but mutually independent objects sharing no mutable
    structure.  A non-bytes aggregate or a public field of the wrong
    type raises :class:`TypeError` (a :class:`bool` never poses as an
    int); an illegal policy, keyring or moment raises
    :class:`ValueError`; an illegal encoding, key set, digest,
    ordering, tally or declaration binding raises
    :class:`InvalidAggregateForkDecisionAggregateError` (a
    :class:`ValueError` subclass); unknown, revoked, not-yet-valid or
    expired credentials or a signature mismatch raise
    :class:`AuthenticationError`.
    """
    if not isinstance(aggregate, bytes):
        raise TypeError("aggregate packet must be bytes")
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_decision_site_policy = _validated_prune_batch_site_policy(
        decision_site_policy
    )
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")
    payload = _verify_pfda_core(
        aggregate,
        validated_prune_policy,
        validated_site_policy,
        validated_decision_site_policy,
        validated_keyring,
        verify_moment,
    )
    authenticated = copy.deepcopy(payload)
    return {
        key: (
            hashlib.sha256(aggregate).hexdigest()
            if key == PFDA_AGGREGATE_DIGEST
            else authenticated[key]
        )
        for key in _PFDA_RESULT_KEYS
    }

        raise TypeError("site policy must be a dict")
    if set(policy.keys()) != _PAC_SITE_POLICY_KEYS:
        raise ValueError(
            "site policy must contain exactly the keys 'sites', "
            "'threshold' and 'policyVersion'"
        )
    policy_version = policy[DS_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("site policy policyVersion must be an int")
    if policy_version <= 0:
        raise ValueError("site policy policyVersion must be a positive integer")
    base = _validated_prune_batch_site_policy({
        ADJ_SITES: policy[ADJ_SITES],
        ADJ_THRESHOLD: policy[ADJ_THRESHOLD],
    })
    base[DS_POLICY_VERSION] = policy_version
    return base


def _pac_site_policy_bytes(policy: dict) -> bytes:
    """Canonical compact bytes of the normalized versioned site policy.

    Sites are listed ascending with ascending version arrays and every
    key is recursively sorted; ``policyVersion`` is bound alongside.
    """
    return _prune_compact({
        ADJ_SITES: {
            site: sorted(policy[ADJ_SITES][site])
            for site in sorted(policy[ADJ_SITES])
        },
        ADJ_THRESHOLD: policy[ADJ_THRESHOLD],
        DS_POLICY_VERSION: policy[DS_POLICY_VERSION],
    })


def _pac_policy_digest(policy: dict) -> str:
    """SHA-256 of the canonical versioned site policy."""
    return hashlib.sha256(_pac_site_policy_bytes(policy)).hexdigest()


def _pac_plain_site_policy(policy: dict) -> dict:
    """The unversioned ``{sites, threshold}`` form a root aggregate binds."""
    return {ADJ_SITES: policy[ADJ_SITES], ADJ_THRESHOLD: policy[ADJ_THRESHOLD]}


def _pac_policy_matches_root(policy: dict, root_view: dict) -> bool:
    """Whether a versioned policy's sites/threshold equal the root policy."""
    unversioned = hashlib.sha256(
        _prune_batch_site_policy_bytes(_pac_plain_site_policy(policy))
    ).hexdigest()
    return hmac.compare_digest(root_view["policy_digest"], unversioned)


# -- Stage views over a root aggregate or a successor packet ------------------

def _pac_root_view(raw: bytes) -> dict:
    """Structurally parse a root prune batch aggregate predecessor."""
    payload, _signature = _parse_prune_batch_aggregate(raw)
    return {
        "kind": "root",
        PAC_ROOT_DIGEST: hashlib.sha256(raw).hexdigest(),
        PAC_HEIGHT: 0,
        STATUS: payload[STATUS],
        PBA_DECLARATION: payload[PBA_DECLARATION],
        PBA_INPUTS: list(payload[PBA_INPUTS]),
        PA_ITEMS: copy.deepcopy(payload[PA_ITEMS]),
        "policy_digest": payload[PBA_SITE_POLICY_DIGEST],
        "prune_policy_digest": payload[PBA_PRUNE_POLICY_DIGEST],
        DS_POLICY_VERSION: PRUNE_BATCH_AGGREGATE_VERSION,
        PAC_EFFECTIVE_AT: None,
    }


def _pac_successor_view(raw: bytes) -> dict:
    """Structurally parse a successor predecessor into a fresh view."""
    payload, _signature, _increment = _parse_pac_successor(raw)
    return {
        "kind": "successor",
        PAC_ROOT_DIGEST: payload[PAC_ROOT_DIGEST],
        PAC_HEIGHT: payload[PAC_HEIGHT],
        STATUS: payload[STATUS],
        PBA_DECLARATION: copy.deepcopy(payload[PBA_DECLARATION]),
        PBA_INPUTS: list(payload[PBA_INPUTS]),
        PA_ITEMS: copy.deepcopy(payload[PA_ITEMS]),
        "policy_digest": payload[PAC_NEW_POLICY_DIGEST],
        "prune_policy_digest": payload[PBA_PRUNE_POLICY_DIGEST],
        DS_POLICY_VERSION: payload[PAC_POLICY_VERSION],
        PAC_EFFECTIVE_AT: payload[PAC_EFFECTIVE_AT],
    }


def _pac_predecessor_view(raw: object) -> dict:
    """Parse predecessor bytes (root aggregate or successor packet).

    The packet kind is chosen from the payload key set so a malformed
    root raises :class:`InvalidPruneBatchAggregateError` while a
    malformed successor raises :class:`InvalidAggregateChainError`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("predecessor must be bytes")
    keys = _packet_payload_keys(raw)
    if keys is not None and PAC_ROOT_DIGEST in keys:
        return _pac_successor_view(raw)
    return _pac_root_view(raw)


# -- Recomputing one aggregate verdict from the stage handovers ---------------

def _pac_sort_rows(rows: list[dict]) -> list[dict]:
    """The bound row order: identity-less rows first, then site then id."""
    return sorted(
        rows,
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        ),
    )


def _tally_prune_chain_rows(
    rows: list[dict], prefix_count: int, threshold: int
) -> tuple[str, list | None]:
    """Re-tally the stage's rows without rewriting the prefix.

    ``rows`` walks the stage in union order -- the predecessor's
    existing statements first (``prefix_count`` of them, already
    site/id-sorted), then the new handover statements -- and the
    existing statements must keep the predecessor's verdict: the
    historical ``valid`` row of one site/content group always wins, so
    a newly appended repeat (even one with a smaller id) can only be a
    ``duplicate``.  A group first formed by this hop follows the root
    aggregation rule: its smallest-id row is ``valid`` and repeats are
    ``duplicate``.  A second distinct declaration from one site
    contradicts every declaration of that site.  Distinct sites must
    share the one declaration; any disagreement is ``conflicted`` and
    no majority can outvote it.  One unique conflict-free declaration
    backed by at least the threshold of distinct sites is ``accepted``;
    short of the threshold it stays ``insufficient`` but keeps that
    declaration; with no valid vote the declaration is null.
    """
    # site -> content bytes -> list of (from-prefix flag, row)
    by_site: dict[str, dict[bytes, list[tuple[bool, dict]]]] = {}
    for position, row in enumerate(rows):
        if row[ADJ_CONCLUSION] in (
            PA_CONCLUSION_VALID,
            PA_CONCLUSION_DUPLICATE,
            PA_CONCLUSION_CONTRADICTION,
        ):
            content = _prune_compact(row[PBA_DECLARATION])
            by_site.setdefault(row[VD_ISSUER], {}).setdefault(
                content, []
            ).append((position < prefix_count, row))

    contradicted = False
    votes: dict[str, bytes] = {}
    representatives: dict[str, dict] = {}
    for site, groups in by_site.items():
        if len(groups) > 1:
            contradicted = True
            ordered_groups = sorted(
                groups.values(),
                key=lambda members: min(member[1][ID] for member in members),
            )
            for members in ordered_groups:
                members.sort(key=lambda member: member[1][ID])
                members[0][1][ADJ_CONCLUSION] = PA_CONCLUSION_CONTRADICTION
                members[0][1][ADJ_REASON] = REASON_CONTRADICTION
                for _from_prefix, extra in members[1:]:
                    extra[ADJ_CONCLUSION] = PA_CONCLUSION_DUPLICATE
                    extra[ADJ_REASON] = REASON_DUPLICATE
        else:
            content, members = next(iter(groups.items()))
            prefix_members = [
                member for member in members if member[0]
            ]
            candidates = prefix_members or members
            winner = min(candidates, key=lambda member: member[1][ID])
            winner[1][ADJ_CONCLUSION] = PA_CONCLUSION_VALID
            winner[1][ADJ_REASON] = None
            for from_prefix, member in members:
                if member is winner[1]:
                    continue
                member[ADJ_CONCLUSION] = PA_CONCLUSION_DUPLICATE
                member[ADJ_REASON] = REASON_DUPLICATE
            votes[site] = content
            representatives[site] = winner[1]

    contents = set(votes.values())
    if contradicted or len(contents) > 1:
        return PA_STATUS_CONFLICTED, None
    if len(contents) == 1:
        common_declaration = copy.deepcopy(
            min(representatives.values(), key=lambda row: row[ID])[
                PBA_DECLARATION
            ]
        )
        if len(votes) >= threshold:
            return PA_STATUS_ACCEPTED, common_declaration
        return PA_STATUS_INSUFFICIENT, common_declaration
    return PA_STATUS_INSUFFICIENT, None


def _pac_recompute(
    prefix_inputs: list[str],
    prefix_rows: list[dict],
    increment: list[dict],
    prune_policy_digest: str,
    prune_threshold: int,
    site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Recompute the complete stage conclusion from prefix plus increment.

    The prefix statements are the already-verified statements of the
    predecessor; each new handover is run through the existing
    aggregation rules and the complete statement set is then re-tallied.
    """
    increment_rows: list[dict] = []
    increment_digests: list[str] = []
    for item in increment:
        digest = hashlib.sha256(item[PBA_PACKET]).hexdigest()
        increment_digests.append(digest)
        increment_rows.append(
            _aggregate_prune_batch_one(
                item, digest, prune_policy_digest, prune_threshold,
                site_policy, validated_keyring, moment,
            )
        )

    full_inputs = list(prefix_inputs) + increment_digests
    working_rows = copy.deepcopy(prefix_rows)
    working_rows.extend(copy.deepcopy(increment_rows))
    status, declaration = _tally_prune_chain_rows(
        working_rows, len(prefix_rows), site_policy[ADJ_THRESHOLD]
    )
    return {
        PBA_INPUTS: full_inputs,
        PA_ITEMS: _pac_sort_rows(working_rows),
        STATUS: status,
        PBA_DECLARATION: declaration,
    }


def _pac_assert_transition(previous: dict, verdict: dict) -> None:
    """Enforce the per-hop verdict state machine.

    ``insufficient`` may gain supplemental evidence and become
    ``accepted`` or ``conflicted``; an ``accepted`` head only keeps the
    identical common declaration or advances to ``conflicted`` (it
    never falls back to insufficient or swaps declarations); a
    ``conflicted`` verdict can never be masked by a later majority.
    """
    prev_status = previous[STATUS]
    new_status = verdict[STATUS]
    if prev_status == PA_STATUS_CONFLICTED:
        if new_status != PA_STATUS_CONFLICTED:
            raise _pac_chain_invalid(
                "a conflicted aggregate can never be outvoted or fall back"
            )
    elif prev_status == PA_STATUS_ACCEPTED:
        if new_status == PA_STATUS_INSUFFICIENT:
            raise _pac_chain_invalid(
                "an accepted aggregate must not fall back to insufficient"
            )
        if new_status == PA_STATUS_ACCEPTED:
            if verdict[PBA_DECLARATION] != previous[PBA_DECLARATION]:
                raise _pac_chain_invalid(
                    "an accepted aggregate may only keep the same common "
                    "declaration"
                )


def _pac_assert_sealer_authorized(
    old_policy: dict, new_policy: dict, issuer: str, key_version: int
) -> None:
    """The successor sealer must be authorized under both site policies."""
    if key_version not in old_policy[ADJ_SITES].get(issuer, frozenset()):
        raise _pac_chain_invalid(
            f"sealer {issuer!r} version {key_version} is not authorized by "
            "the previous site policy"
        )
    if key_version not in new_policy[ADJ_SITES].get(issuer, frozenset()):
        raise _pac_chain_invalid(
            f"sealer {issuer!r} version {key_version} is not authorized by "
            "the rotated site policy"
        )


def _pac_validated_increment(increment: object) -> list[dict]:
    """Validate a sealing-stage handover increment, which may be empty.

    A non-empty increment follows the exact
    :func:`aggregate_prune_batches` item rules; an empty increment is
    only meaningful for a policy rotation (the append rule enforces a
    non-empty increment when the policy is unchanged).
    """
    if not isinstance(increment, list):
        raise TypeError("increment must be a list")
    if not increment:
        return []
    return _validated_prune_batch_items(increment)


def _pac_assert_extends(
    previous: dict, full_inputs: list[str], increment: list[dict],
    unchanged: bool,
) -> None:
    """Enforce the append-only handover prefix and disjoint identities.

    The predecessor's handover digests must remain the ordered prefix
    of the stage -- nothing is deleted, changed or reordered -- and a
    non-empty increment adds only new packet digests and new item ids.
    An unchanged policy must add at least one handover; a rotation may
    re-seal the identical sequence with an empty increment.
    """
    prefix_inputs = previous[PBA_INPUTS]
    if unchanged and not increment:
        raise _pac_chain_invalid("an unchanged policy requires new handovers")
    if len(full_inputs) < len(prefix_inputs):
        raise _pac_chain_invalid(
            "the handover sequence must extend the predecessor"
        )
    if full_inputs[:len(prefix_inputs)] != prefix_inputs:
        raise _pac_chain_invalid(
            "the handover sequence must keep the predecessor as an ordered "
            "prefix; history must not be deleted, changed or reordered"
        )
    prefix_digests = set(prefix_inputs)
    prefix_ids = {row[ID] for row in previous[PA_ITEMS]}
    seen_digests: set[str] = set()
    seen_ids: set[str] = set()
    for item in increment:
        digest = hashlib.sha256(item[PBA_PACKET]).hexdigest()
        if digest in prefix_digests or digest in seen_digests:
            raise _pac_chain_invalid(
                "a handover packet already in the prefix must not be appended "
                "again"
            )
        seen_digests.add(digest)
        item_id = item[ID]
        if item_id in prefix_ids or item_id in seen_ids:
            raise _pac_chain_invalid(
                f"handover item id {item_id!r} is already part of the chain"
            )
        seen_ids.add(item_id)


# -- Successor packet shape ----------------------------------------------------

def _pac_bound_increment(raw_items: object, where: str) -> list[dict]:
    """Parse the raw handover increment bound inside a successor packet.

    Each entry carries exactly ``id`` and ``packet``; packet bytes ride
    as non-empty even-length lowercase hex.  A field of the wrong type
    raises :class:`TypeError`; every key-set, value or hex fault raises
    :class:`InvalidAggregateChainError`.
    """
    if not isinstance(raw_items, list):
        raise TypeError(f"{where} handovers must be a list")
    validated: list[dict] = []
    for position, item in enumerate(raw_items):
        item_where = f"{where} handover {position}"
        if not isinstance(item, dict):
            raise TypeError(f"{item_where} must be an object")
        if set(item.keys()) != _PAC_INCREMENT_ITEM_KEYS:
            raise _pac_chain_invalid(
                f"{item_where} must contain exactly the keys 'id' and 'packet'"
            )
        item_id = item[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{item_where} id must be a str")
        if item_id == "":
            raise _pac_chain_invalid(f"{item_where} id must be non-empty")
        packet_hex = item[PAC_PACKET]
        if not isinstance(packet_hex, str):
            raise TypeError(f"{item_where} packet must be a str")
        try:
            packet = _hex_bytes(packet_hex)
        except ValueError as exc:
            raise _pac_chain_invalid(
                f"{item_where} packet must be non-empty even-length lowercase "
                "hex"
            ) from exc
        validated.append({ID: item_id, PAC_PACKET: packet})
    return validated


def _pac_validated_rows(raw_rows: object, where: str) -> list[dict]:
    """Validate the bound aggregate rows of a successor payload.

    The row contract is the one :func:`aggregate_prune_batches` binds,
    but every structural fault raises
    :class:`InvalidAggregateChainError` and a wrong JSON type raises
    :class:`TypeError`.
    """
    if not isinstance(raw_rows, list):
        raise TypeError(f"{where} items must be a list")
    if not raw_rows:
        raise _pac_chain_invalid(f"{where} items must be a non-empty list")
    parsed_rows: list[dict] = []
    seen_ids: set[str] = set()
    for position, row in enumerate(raw_rows):
        row_where = f"{where} item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be an object")
        if set(row.keys()) != _PBA_ROW_KEYS:
            raise _pac_chain_invalid(
                f"{row_where} must contain exactly the keys 'conclusion', "
                "'digest', 'id', 'issuer', 'keyVersion', 'reason' and "
                "'declaration'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{row_where} id must be a str")
        if row_id == "":
            raise _pac_chain_invalid(f"{row_where} id must be non-empty")
        if row_id in seen_ids:
            raise _pac_chain_invalid(f"{row_where} repeats an id")
        seen_ids.add(row_id)
        digest = row[CP_DIGEST]
        if not _prune_is_digest(digest):
            raise _pac_chain_invalid(
                f"{row_where} digest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None and not isinstance(site, str):
            raise TypeError(f"{row_where} issuer must be a str or null")
        if site == "":
            raise _pac_chain_invalid(f"{row_where} issuer must be non-empty")
        key_version = row[KEY_VERSION]
        if isinstance(key_version, bool) or not isinstance(key_version, int):
            if key_version is not None:
                raise TypeError(
                    f"{row_where} keyVersion must be an int or null"
                )
        elif key_version <= 0:
            raise _pac_chain_invalid(
                f"{row_where} keyVersion must be positive"
            )
        if (site is None) != (key_version is None):
            raise _pac_chain_invalid(
                f"{row_where} issuer and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]
        if not isinstance(conclusion, str):
            raise TypeError(f"{row_where} conclusion must be a str")
        reason = row[ADJ_REASON]
        if conclusion == PA_CONCLUSION_VALID:
            if reason is not None:
                raise _pac_chain_invalid(
                    f"{row_where} reason must be null for a valid row"
                )
        elif conclusion == PA_CONCLUSION_INVALID:
            if reason not in _PBA_INVALID_REASONS:
                raise _pac_chain_invalid(
                    f"{row_where} reason must be one of 'invalid', "
                    "'unauthenticated' or 'unauthorized'"
                )
        elif conclusion in (
            PA_CONCLUSION_DUPLICATE, PA_CONCLUSION_CONTRADICTION
        ):
            expected = (
                REASON_DUPLICATE
                if conclusion == PA_CONCLUSION_DUPLICATE
                else REASON_CONTRADICTION
            )
            if reason != expected:
                raise _pac_chain_invalid(
                    f"{row_where} reason must match its conclusion"
                )
        else:
            raise _pac_chain_invalid(f"{row_where} conclusion is not known")
        identity_present = reason != PA_CONCLUSION_INVALID
        if identity_present:
            if site is None:
                raise _pac_chain_invalid(
                    f"{row_where} an authenticated or authorized row must "
                    "carry its issuer"
                )
        elif site is not None:
            raise _pac_chain_invalid(
                f"{row_where} an invalid row must carry no issuer"
            )
        if conclusion == PA_CONCLUSION_INVALID:
            if row[PBA_DECLARATION] is not None:
                raise _pac_chain_invalid(
                    f"{row_where} an invalid row must carry no declaration"
                )
            declaration = None
        else:
            if not isinstance(row[PBA_DECLARATION], list):
                raise TypeError(
                    f"{row_where} declaration must be a list"
                )
            declaration = _validated_signed_batch_items(
                row[PBA_DECLARATION], _pac_chain_invalid,
                f"{row_where} declaration",
            )
        parsed_rows.append({
            ADJ_CONCLUSION: conclusion,
            CP_DIGEST: digest,
            ID: row_id,
            VD_ISSUER: site,
            KEY_VERSION: key_version,
            ADJ_REASON: reason,
            PBA_DECLARATION: declaration,
        })
    return parsed_rows


def _parse_pac_successor(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate successor bytes into ``(payload, signature, increment)``.

    A non-bytes argument or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, row or increment fault raises
    :class:`InvalidAggregateChainError`.  The predecessor, policy,
    moment, tally and signature bindings are checked by the chain
    verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("successor must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _pac_chain_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _pac_chain_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_pac_keys
        )
    except json.JSONDecodeError as exc:
        raise _pac_chain_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("successor must be a JSON object")
    if set(data.keys()) != _PAC_TOP_KEYS:
        raise _pac_chain_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("successor signature must be a str")
    if _PRUNE_HEX64.fullmatch(signature) is None:
        raise _pac_chain_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("successor payload must be an object")
    if set(payload.keys()) != _PAC_SUCCESSOR_PAYLOAD_KEYS:
        raise _pac_chain_invalid("payload must contain exactly the bound keys")

    for key in (
        PAC_ROOT_DIGEST, PAC_PREDECESSOR_DIGEST,
        PBA_PRUNE_POLICY_DIGEST, PAC_OLD_POLICY_DIGEST, PAC_NEW_POLICY_DIGEST,
    ):
        value = payload[key]
        if not isinstance(value, str):
            raise TypeError(f"payload {key} must be a str")
        if not _prune_is_digest(value):
            raise _pac_chain_invalid(
                f"payload {key} must be 64 lowercase hex characters"
            )
    height = payload[PAC_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError("payload height must be an int")
    if height < 1:
        raise _pac_chain_invalid("payload height must be a positive integer")
    policy_version = payload[PAC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("payload policyVersion must be an int")
    if policy_version <= 0:
        raise _pac_chain_invalid("payload policyVersion must be positive")
    effective = payload[PAC_EFFECTIVE_AT]
    if isinstance(effective, bool) or not isinstance(effective, int):
        raise TypeError("payload effectiveAt must be an int")
    if effective < 0:
        raise _pac_chain_invalid("payload effectiveAt must be non-negative")
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _pac_chain_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _pac_chain_invalid("payload keyVersion must be positive")
    packet_version = payload[VERSION]
    if isinstance(packet_version, bool) or not isinstance(
        packet_version, int
    ):
        raise TypeError("payload version must be an int")
    if packet_version != PRUNE_AGGREGATE_CHAIN_VERSION:
        raise _pac_chain_invalid("payload version must be the integer 1")

    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("payload status must be a str")
    if status not in _PA_STATUSES:
        raise _pac_chain_invalid("payload status is not known")

    inputs = payload[PBA_INPUTS]
    if not isinstance(inputs, list):
        raise TypeError("payload inputs must be a list")
    if not inputs:
        raise _pac_chain_invalid("payload inputs must be a non-empty list")
    for position, digest in enumerate(inputs):
        if not _prune_is_digest(digest):
            raise _pac_chain_invalid(
                f"payload input {position} digest must be 64 lowercase hex "
                "characters"
            )

    rows = _pac_validated_rows(payload[PA_ITEMS], "payload")
    if len(rows) != len(inputs):
        raise _pac_chain_invalid(
            "the items must cover every handover and vice versa"
        )
    raw_declaration = payload[PBA_DECLARATION]
    if raw_declaration is None:
        declaration = None
    else:
        if not isinstance(raw_declaration, list):
            raise TypeError("payload declaration must be a list or null")
        declaration = _validated_signed_batch_items(
            raw_declaration, _pac_chain_invalid, "payload declaration"
        )
    if status == PA_STATUS_ACCEPTED and declaration is None:
        raise _pac_chain_invalid(
            "an accepted verdict must keep the common declaration"
        )
    if status == PA_STATUS_CONFLICTED and declaration is not None:
        raise _pac_chain_invalid(
            "a conflicted verdict must bind a null common declaration"
        )

    increment = _pac_bound_increment(payload[PAC_HANDOVERS], "payload")

    normalized_payload = {
        PAC_ROOT_DIGEST: payload[PAC_ROOT_DIGEST],
        PAC_PREDECESSOR_DIGEST: payload[PAC_PREDECESSOR_DIGEST],
        PAC_HEIGHT: height,
        PBA_INPUTS: list(inputs),
        PA_ITEMS: rows,
        PBA_DECLARATION: declaration,
        STATUS: status,
        PBA_PRUNE_POLICY_DIGEST: payload[PBA_PRUNE_POLICY_DIGEST],
        PAC_OLD_POLICY_DIGEST: payload[PAC_OLD_POLICY_DIGEST],
        PAC_NEW_POLICY_DIGEST: payload[PAC_NEW_POLICY_DIGEST],
        PAC_POLICY_VERSION: policy_version,
        PAC_EFFECTIVE_AT: effective,
        PAC_HANDOVERS: [
            {ID: item[ID], PAC_PACKET: item[PAC_PACKET].hex()}
            for item in increment
        ],
        VD_ISSUER: issuer,
        KEY_VERSION: key_version,
        VERSION: PRUNE_AGGREGATE_CHAIN_VERSION,
    }
    if _prune_compact({TICKET_PAYLOAD: normalized_payload,
                       SIGNATURE: signature}) != raw:
        raise _pac_chain_invalid(
            "encoding is not the canonical compact form"
        )
    return normalized_payload, signature, increment


# -- Sealing a successor -------------------------------------------------------

def supersede_prune_aggregate(
    predecessor, increment, prune_policy, old_policy, new_policy, keyring,
    moment, effective_at, issuer, version
):
    """Issue one signed supersession successor over a prune batch aggregate.

    ``predecessor`` is either the chain root (an
    :func:`aggregate_prune_batches` packet) or the previous successor
    packet.  ``increment`` is the stage's non-empty list of new
    handover items in the exact shape of :func:`aggregate_prune_batches`
    items -- each exactly a unique non-empty ``id`` and ``packet``
    bytes (a :func:`sign_prune_adjudication_batch` handover).  The
    stage keeps every predecessor handover verbatim as an ordered
    digest prefix and only appends the increment; existing statements
    are never deleted, changed or reordered.  ``prune_policy`` is the
    original ``{"batch", "sites", "threshold"}`` pruning policy,
    invariant along the whole chain; ``old_policy``/``new_policy``
    carry exactly ``sites``, ``threshold`` and a positive
    ``policyVersion``: unchanged sites and threshold keep the version,
    any content change increments it by exactly one.  ``effective_at``
    is the hop's non-negative effective moment and never moves
    backwards; ``moment`` is the issuance/verification moment and
    ``issuer``/``version`` name the successor sealing key, which must
    be authorized under both policies and usable at both moments.

        where = f"item {position}"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if set(item.keys()) != _PAC_CHAIN_ITEM_KEYS:
            raise ValueError(
                f"{where} must contain exactly the keys 'id', 'policies', "
                "'root' and 'successors'"
            )
        item_id = item[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{where} id must be a str")
        if item_id == "":
            raise ValueError(f"{where} id must be non-empty")
        if item_id in seen_ids:
            raise ValueError(f"duplicate id {item_id!r}")
        seen_ids.add(item_id)
        root = item[PAC_BATCH_ROOT]
        if not isinstance(root, bytes):
            raise TypeError(f"{where} root must be bytes")
        successors = item[PAC_BATCH_SUCCESSORS]
        if not isinstance(successors, list):
            raise TypeError(f"{where} successors must be a list")
        for hop_index, successor in enumerate(successors):
            if not isinstance(successor, bytes):
                raise TypeError(f"{where} successor {hop_index} must be bytes")
        policies = item[PAC_BATCH_POLICIES]
        validated_policies = _pac_validated_policy_sequence(policies)
        if len(validated_policies) != len(successors) + 1:
            raise ValueError(
                f"{where} policies must provide one entry per chain stage "
                "(one more than the number of successors)"
            )
        if validated_policies[0][DS_POLICY_VERSION] != 1:
            raise ValueError(
                f"{where} root stage policy must carry policyVersion 1"
            )
        validated.append({
            ID: item_id,
            PAC_BATCH_ROOT: root,
            PAC_BATCH_SUCCESSORS: list(successors),
            PAC_BATCH_POLICIES: list(policies),
        })
    return validated


def _pac_chain_edge_nodes(item: dict) -> list[str]:
    """The digest chain a batch item walks: root then each successor."""
    nodes = [hashlib.sha256(item[PAC_BATCH_ROOT]).hexdigest()]
    for successor in item[PAC_BATCH_SUCCESSORS]:
        nodes.append(hashlib.sha256(successor).hexdigest())
    return nodes


def _pac_chain_item_report(
    item_id: str, status: str, error: str | None, result: dict | None
) -> dict:
    """One prune aggregate chain batch report with the fixed key order."""
    return {
        CHECKPOINT_ITEM_ERROR: error,
        ID: item_id,
        VERDICT_ITEM_RESULT: result,
        STATUS: status,
    }


def _verify_pac_chain_item(
    item: dict, prune_policy: object, keyring: object, verify_moment: int
) -> dict:
    """Verify one batch chain in isolation and report its outcome.

    The root aggregate is verified on its own first, so a root fault is
    reported ``invalid-root`` while a successor or chain-binding fault
    is ``invalid-chain``; credential and signature faults are
    ``unauthenticated`` and a passing chain is ``verified``.  A
    :class:`TypeError` here can only come from a wrong field type
    *inside* a packet; the public argument types were all validated
    before the batch ran.
    """
    item_id = item[ID]
    root = item[PAC_BATCH_ROOT]
    successors = item[PAC_BATCH_SUCCESSORS]
    policies = item[PAC_BATCH_POLICIES]
    try:
        verify_prune_aggregate_chain(
            root, [], prune_policy, policies[:1], keyring, verify_moment
        )
    except AuthenticationError as exc:
        return _pac_chain_item_report(
            item_id, PAC_CHAINS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidPruneBatchAggregateError, TypeError, ValueError) as exc:
        return _pac_chain_item_report(
            item_id, PAC_CHAINS_INVALID_ROOT, str(exc), None
        )
    try:
        result = verify_prune_aggregate_chain(
            root, successors, prune_policy, policies, keyring, verify_moment
        )
    except AuthenticationError as exc:
        return _pac_chain_item_report(
            item_id, PAC_CHAINS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidPruneBatchAggregateError, InvalidAggregateChainError,
            TypeError, ValueError) as exc:
        return _pac_chain_item_report(
            item_id, PAC_CHAINS_INVALID_CHAIN, str(exc), None
        )
    return _pac_chain_item_report(
        item_id, PAC_CHAINS_VERIFIED, None, result
    )


def verify_prune_aggregate_chains(items, prune_policy, keyring, moment):
    """Verify a batch of prune aggregate chains and spot successor forks.

    Each item holds exactly a unique non-empty ``id``, its ``root``
    aggregate packet, its ordered ``successors`` packets and its
    per-stage ``policies`` history; ``prune_policy`` is the invariant
    original pruning policy shared by every chain, and ``keyring`` and
    ``moment`` keep their single-chain meaning.  The whole batch
    structure -- every key set, element type, policy count and the
    shared materials -- is validated before any chain is verified, so
    only these batch-level faults raise: container, element or field
    type faults raise :class:`TypeError` (a :class:`bool` never poses
    as an int) and an empty list, an empty or duplicate id, a wrong
    policy count or an illegal moment raises :class:`ValueError`.

    Each chain is then verified independently, in strict input order,
    through the exact :func:`verify_prune_aggregate_chain` rules: one
    chain's failure never stops a later chain or changes an earlier
    report.  A root fault reports ``invalid-root``, a successor or
    chain-binding fault ``invalid-chain`` and a credential or signature
    fault ``unauthenticated``, each with a null ``result``; a passing
    chain reports ``verified``.

    The verified chains are then grouped by their ``rootDigest`` and
    only successor trajectories under the same aggregate root are
    compared: the same predecessor digest pointing at two distinct
    successor digests is a fork (a mere prefix extension -- the same
    chain growing longer -- is not).  Every verified chain crossing a
    forking edge is reclassified ``conflicted`` with its verified
    result kept and its ``error`` fixed to ``"forked-aggregate-chain"``;
    invalid and unauthenticated chains are never reclassified.

    Returns a fresh dict with the fixed keys ``forks``, ``items`` and
    ``version`` (the integer 1).  ``forks`` is sorted by ``rootDigest``
    then ``predecessorDigest``; each entry carries exactly
    ``rootDigest``, ``predecessorDigest``, ``successors`` (the forking
    successor digests, ascending) and ``ids`` (the ascending ids of the
    chains crossing the edge).  Each item report preserves the input
    order and carries, in this key order, ``error`` (null exactly when
    verified), ``id``, ``result`` (the single-chain summary when the
    chain verified, otherwise null) and ``status``.  No file is read or
    written and no input is modified.
    """
    validated_items = _validated_pac_chain_batch(items)
    _validated_adjudication_policy(prune_policy)
    _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    reports: list[dict] = []
    results: list[dict | None] = []
    for item in validated_items:
        report = _verify_pac_chain_item(
            item, prune_policy, keyring, verify_moment
        )
        reports.append(report)
        results.append(report[VERDICT_ITEM_RESULT])

    # Fork detection within each aggregate-root group: one predecessor
    # digest pointing at two distinct successor digests, ignoring
    # chains that did not verify.
    groups: dict[str, dict[str, set[str]]] = {}
    for item, result in zip(validated_items, results):
        if result is None:
            continue
        nodes = _pac_chain_edge_nodes(item)
        edges = groups.setdefault(nodes[0], {})
        for upstream, downstream in zip(nodes, nodes[1:]):
            edges.setdefault(upstream, set()).add(downstream)
    fork_edges: dict[tuple[str, str], list[str]] = {}
    for root_digest, edges in groups.items():
        for upstream, digests in edges.items():
            if len(digests) > 1:
                fork_edges[(root_digest, upstream)] = sorted(digests)
    edge_ids: dict[tuple[str, str], set[str]] = {
        edge: set() for edge in fork_edges
    }
    if fork_edges:
        for item, report, result in zip(validated_items, reports, results):
            if result is None:
                continue
            nodes = _pac_chain_edge_nodes(item)
            crosses_fork = False
            for upstream in nodes[:-1]:
                edge = (nodes[0], upstream)
                if edge in fork_edges:
                    edge_ids[edge].add(item[ID])
                    crosses_fork = True
            if crosses_fork:
                report[STATUS] = PAC_CHAINS_CONFLICTED
                report[CHECKPOINT_ITEM_ERROR] = _PAC_CHAIN_ITEM_ERROR

    forks = [
        {
            PAC_ROOT_DIGEST: root_digest,
            PAC_PREDECESSOR_DIGEST: predecessor,
            PAC_BATCH_SUCCESSORS: fork_edges[(root_digest, predecessor)],
            _FORK_IDS: sorted(edge_ids[(root_digest, predecessor)]),
        }
        for root_digest, predecessor in sorted(fork_edges)
    ]
    return {
        CHAINS_FORKS: forks,
        ITEMS: reports,
        VERSION: PRUNE_AGGREGATE_CHAINS_VERSION,
    }


